WITH cleaned AS (SELECT id, customer_id, start_date, monthly_fee, status, DATEDIFF(CURRENT_DATE(), start_date) / 365 AS years_since_start_date, CONCAT_WS('/', status, plan) AS status_plan_key FROM subscriptions WHERE end_date >= DATE '2023-10-27' AND plan = 'premium') SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY monthly_fee DESC, id ASC) AS rn FROM cleaned QUALIFY rn = 1
